export function appPage(): string {
  return enhancePage(basePage().replace('<title>Studio</title>', '<title>OSS Studio</title>'));
}

export function oauthCallbackPage(): string {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="/osaii.png" type="image/png"><title>Signing in with ChatGPT · OSS Studio</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#000;color:#f5f5f1;font:15px system-ui,sans-serif}.card{max-width:420px;padding:28px;border:1px solid #242424;border-radius:16px;background:#0b0b0c}.muted{color:#a7a7a0;line-height:1.6}</style></head><body><main class="card"><h1>Finishing ChatGPT sign-in…</h1><p class="muted" id="status">Securely saving your browser session. This page will return to OSS Studio automatically.</p></main><script type="module">import{completeLogin}from"https://esm.sh/@openai-oauth/web@2.0.0";const s=document.querySelector('#status');try{await completeLogin();location.replace('/studio')}catch(e){s.textContent=e?.message||'ChatGPT sign-in could not be completed. Return to Studio and try again.'}</script></body></html>`;
}

