function sanitize(h){const t=document.createElement('template');t.innerHTML=h;t.content.querySelectorAll('*').forEach(el=>{for(const a of [...el.attributes]){if(!(a.name==='href'&&/^https?:|^mailto:|^#/.test(a.value)))el.removeAttribute(a.name)}if(!ALLOWED.has(el.tagName)){el.replaceWith(...el.childNodes);return}if(el.tagName==='A'&&!el.getAttribute('href'))el.removeAttribute('href')});return t.innerHTML}
