let rafTimer=null,followRaf=null,streamEpoch=0,stateFollowing=true,programmaticScroll=false;const streamNearBottom=()=>feed.scrollHeight-feed.scrollTop-feed.clientHeight<120;function updateFollowArrow(){followStream.hidden=!state.streaming||stateFollowing}function scheduleLatestScroll(){if(!stateFollowing||followRaf)return;followRaf=requestAnimationFrame(()=>{followRaf=null;if(!stateFollowing)return;programmaticScroll=true;feed.scrollTop=feed.scrollHeight;updateFollowArrow();requestAnimationFrame(()=>{programmaticScroll=false})})}function followLatest(){stateFollowing=true;scheduleLatestScroll();updateFollowArrow()}feed.addEventListener('scroll',()=>{if(programmaticScroll)return;stateFollowing=streamNearBottom();updateFollowArrow()});followStream.onclick=followLatest;function clearStreamingFrame(){streamEpoch++;if(rafTimer){cancelAnimationFrame(rafTimer);rafTimer=null}if(followRaf){cancelAnimationFrame(followRaf);followRaf=null}}function renderStreaming(el,content){state.streaming=true;const epoch=++streamEpoch;if(rafTimer)cancelAnimationFrame(rafTimer);rafTimer=requestAnimationFrame(()=>{rafTimer=null;if(epoch!==streamEpoch||!el.isConnected)return;el.innerHTML=escapeHtml(content).replace(/\\n/g,'<br>');el.classList.add('streaming');scheduleLatestScroll();updateFollowArrow()})}
