function createAgentActivity(label){const panel=document.createElement('div');panel.className='agent-activity';panel.hidden=true;panel.innerHTML='<div class="agent-activity-head"><span>'+escapeHtml(label||'Agent activity')+'</span><span class="agent-activity-label">Live</span></div><div class="agent-activity-current">Waiting for a tool call…</div><div class="agent-activity-previous"></div>';feed.append(panel);const current=panel.querySelector('.agent-activity-current'),previous=panel.querySelector('.agent-activity-previous');const formatArgs=value=>{const text=String(value||'').replace(/\s+/g,' ').trim();return text.length>280?text.slice(0,280)+'…':text};return{call(name,detail){panel.hidden=false;current.textContent='Running '+name+(detail?' · '+formatArgs(detail):'')+'…';current.dataset.tool=name},args(name,partial){panel.hidden=false;const text=formatArgs(partial);current.textContent='Running '+name+(text?' · args: '+text:' · waiting for args…')+'…';current.dataset.tool=name;current.dataset.args=String(partial||'')},complete(name,status='ok'){panel.hidden=false;const row=document.createElement('div');const kind=status===true||status==='ok'?'ok':status===false?'failed':status;row.className='activity-'+kind;row.textContent=kind==='blocked'?'Blocked by permissions: '+name:kind==='failed'?'Failed: '+name:'Completed: '+name;previous.append(row);current.textContent='No active tool call';delete current.dataset.tool;delete current.dataset.args},phase(text){panel.hidden=false;current.textContent=text},finish(){if(!previous.children.length)panel.hidden=true;else current.textContent='All calls complete'}}}
