const backupStoreKey='osaii.chats.backup.v1';
function chatStorages(){const out=[];for(const getter of [()=>localStorage,()=>sessionStorage]){try{out.push(getter())}catch{}}return out}
function titleText(value){if(typeof value==='string')return value;if(Array.isArray(value))return value.map(part=>typeof part==='string'?part:(part?.text||part?.content||'')).join(' ');if(value&&typeof value==='object')return value.text||value.content||'';return String(value??'')}
function chatTitleFromMessages(messages){const first=(Array.isArray(messages)?messages:[]).find(m=>m&&m.role==='user');return autoChatTitle(titleText(first?.content))}
function normalizeChat(chat){if(!chat||typeof chat.id!=='string'||!Array.isArray(chat.messages))return null;const title=typeof chat.title==='string'&&chat.title.trim()&&chat.title.trim()!=='New conversation'?chat.title.trim():chatTitleFromMessages(chat.messages);return {...chat,title:title||'New conversation'} }
