function newChat(){state.abort?.abort();state.abort=null;state.chatId=null;state.messages=[];state.streaming=false;feed.innerHTML='';document.querySelector('#welcome').classList.remove('hidden');send.disabled=false;send.textContent='Send ↗';renderHistory()}
