function deleteChat(id){const chats=loadChats().filter(c=>c.id!==id);saveChats(chats);if(id===state.chatId){state.chatId=null;state.messages=[];feed.innerHTML='';document.querySelector('#welcome').classList.remove('hidden');setStreaming(false)}renderHistory()}
function autoChatTitle(text){let title=String(text||'').replace(/\\s+/g,' ').replace(/^[\\s.!?]+|[\\s.!?]+$/g,'').split(/[.!?](?:\\s|$)/)[0].trim();title=title.replace(/^(please|can you|could you|would you)\\s+/i,'').replace(/^make (the )?source code for /i,'').replace(/^help me (to )?/i,'');if(title.length>54)title=title.slice(0,54).replace(/\\s+\\S*$/,'');return title?title.charAt(0).toUpperCase()+title.slice(1):'New conversation'}
function saveCurrentChat(){if(!state.messages.length||!state.messages.some(m=>m&&m.role==='user'))return;if(!state.chatId)state.chatId=Date.now().toString(36)+Math.random().toString(36).slice(2,6);const title=chatTitleFromMessages(state.messages);const chats=loadChats();const idx=chats.findIndex(c=>c.id===state.chatId);const chat={id:state.chatId,title:title||'New conversation',mode:state.mode,tier:state.tier,advanced:state.advanced,reasoning:state.reasoning,permission:state.permission,messages:state.messages.slice(),updatedAt:Date.now()};if(idx>=0)chats[idx]=chat;else chats.unshift(chat);chats.sort((a,b)=>b.updatedAt-a.updatedAt);saveChats(chats.slice(0,50));renderHistory()}
function setStreaming(on){state.streaming=on;if(on)stateFollowing=true;send.textContent=on?'Stop':'Send ↗';send.disabled=false;updateFollowArrow()}
function stopStream(){state.abort?.abort()}
