const originalOpenChat=openChat;openChat=id=>{originalOpenChat(id);const reasoning=q('#reasoning');if(reasoning&&!reasoning.options.length)reasoning.innerHTML='<option value="none">Reasoning: None</option><option value="low">Reasoning: Light</option><option value="medium">Reasoning: Medium</option><option value="xhigh">Reasoning: Max</option>';if(reasoning)reasoning.value=state.reasoning||'low';renderModelControls()};
