renderModelControls=()=>{const family=q('#speed'),advanced=q('#advancedModel'),chatgpt=q('#chatgptModel'),chatgptFamily=q('#chatgptFamily');const usingChatGPT=state.chatgptMode===true||(typeof state.advanced==='string'&&state.advanced.startsWith('chatgpt/'));if(family)family.value=usingChatGPT?'chatgpt':state.tier;if(advanced){advanced.classList.toggle('hidden',usingChatGPT||state.tier!=='advanced');advanced.disabled=usingChatGPT||state.tier!=='advanced';if(!usingChatGPT&&state.tier==='advanced'&&state.advanced)advanced.value=state.advanced}if(chatgpt){chatgpt.classList.toggle('hidden',!usingChatGPT);chatgpt.disabled=!usingChatGPT;if(usingChatGPT&&state.advanced)chatgpt.value=state.advanced}if(chatgptFamily){chatgptFamily.hidden=false;chatgptFamily.disabled=!state.chatgptSignedIn||!chatGPTModels.length;chatgptFamily.textContent=state.chatgptSignedIn&&chatGPTModels.length?'ChatGPT / Codex':'ChatGPT / Codex (sign in)'}if(family)document.querySelector('#modelLabel').textContent=usingChatGPT?'CHATGPT · '+(chatgpt?.options?.[chatgpt.selectedIndex]?.text||state.chatgptModel||'Codex'):state.tier==='advanced'?'ADVANCED · '+(advanced?.options?.[advanced.selectedIndex]?.text||'Advanced'):state.tier==='smart'?'SMART · Laguna S':'FAST · Laguna XS'};
