function readableError(data,fallback='The request could not be completed.'){const value=data?.error??data?.message;if(typeof value==='string'&&value.trim())return value;if(value&&typeof value==='object'&&typeof value.message==='string')return value.message;try{if(value)return JSON.stringify(value)}catch{}return fallback}
async function ask(messages,model){const r=await fetch('/studio/api/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({model,messages,...requestControls(model)})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(readableError(d));return d.choices?.[0]?.message?.content||'No response returned.'}
function reasoningBudgetNotice(){return 'The model used its full reasoning budget before producing a final answer. Try again with a larger token budget or a shorter prompt.'}
async function askStream(messages,model,onDelta,onReasoning){const controller=new AbortController();state.abort=controller;const requestBody={model,messages,...requestControls(model),stream:true,stream_options:{include_usage:true}};const r=await fetch('/studio/api/chat',{method:'POST',headers:{'content-type':'application/json',accept:'text/event-stream'},body:JSON.stringify(requestBody),signal:controller.signal});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(readableError(d))}if(!r.body)return '';const reader=r.body.getReader();const dec=new TextDecoder();let buf='',raw='',content='',reasoning='',sawSse=false;const consumeLine=line=>{const text=line.trim();if(!text.startsWith('data:'))return;sawSse=true;const payload=text.slice(5).trim();if(payload==='[DONE]')return;let j;try{j=JSON.parse(payload)}catch{return}if(j.error)throw new Error(readableError(j,'Upstream provider error'));const delta=j.choices?.[0]?.delta||{};const thought=typeof delta.reasoning_content==='string'?delta.reasoning_content:'';if(thought){reasoning+=thought;if(onReasoning)onReasoning(reasoning)}const piece=typeof delta.content==='string'?delta.content:'';if(piece){content+=piece;onDelta(content)}};const flushComplete=()=>{let i;while((i=buf.indexOf('\\n'))>=0){consumeLine(buf.slice(0,i));buf=buf.slice(i+1)}};try{while(true){const {done,value}=await reader.read();if(done)break;const text=dec.decode(value,{stream:true});raw+=text;buf+=text;flushComplete()}const tail=dec.decode();if(tail){raw+=tail;buf+=tail}flushComplete();if(buf.trim())consumeLine(buf)}catch(e){if(e.name!=='AbortError')throw e}if(!sawSse&&raw.trim()){try{const j=JSON.parse(raw);const fallback=j.choices?.[0]?.message?.content;if(typeof fallback==='string'){content=fallback;onDelta(content)}else if(j.choices?.[0]?.message?.reasoning_content){content=reasoningBudgetNotice();onDelta(content)}}catch{}}return content|| (reasoning ? reasoningBudgetNotice() : '')}
async function run(){const text=prompt.value.trim();if(!text)return;prompt.value='';document.querySelector('#welcome').classList.add('hidden');addMessage('user',text);state.messages.push({role:'user',content:text});saveCurrentChat();let el=null;try{let out;if(state.mode==='swarm'){el=addMessage('assistant','Launching 300 independent passes…');setTyping(el,true);send.disabled=true;send.textContent='Working…';const tasks=Array.from({length:300},(_,i)=>ask([{role:'system',content:'You are researcher '+(i+1)+' in a parallel team. Give one compact, concrete angle. Do not repeat the task.'},{role:'user',content:text}],fast).catch(()=>''));const findings=(await Promise.all(tasks)).filter(Boolean).slice(0,300);setTyping(el,false);el.textContent='Delegator is combining '+findings.length+' perspectives…';out=await askStream([{role:'system',content:'You are the lead delegator. Synthesize the team findings into a direct, useful answer with a recommendation.'},{role:'user',content:'Task: '+text+'\\n\\nFindings:\\n'+findings.join('\\n---\\n')}],smart,c=>{setTyping(el,false);renderStreaming(el,c)});}else{setStreaming(true);const system=state.mode==='agent'?'You are a practical web-aware task agent. Break work into clear steps, state what you can verify, and give the user a direct result.':'You are a clear, helpful assistant for everyday people.';el=addMessage('assistant','',{typing:true});out=await askStream([{role:'system',content:system},...state.messages],selectedModel(),c=>{setTyping(el,false);renderStreaming(el,c)});}if(out){setTyping(el,false);el.classList.remove('streaming');renderMessage('assistant',out,el);state.messages.push({role:'assistant',content:out});}else if(state.abort?.signal.aborted){el.remove();}else{setTyping(el,false);el.classList.remove('streaming');renderMessage('assistant','No response returned.',el);state.messages.push({role:'assistant',content:'No response returned.'});}saveCurrentChat()}catch(e){if(e.name!=='AbortError'){if(el){setTyping(el,false);el.classList.remove('streaming');renderMessage('assistant','Could not complete that: '+e.message,el)}else{addMessage('assistant','Could not complete that: '+e.message)}}}finally{clearStreamingFrame();state.abort=null;setStreaming(false);send.disabled=false;prompt.focus()}}
const baseRun=run;run=async()=>{const activeMode=qa('[data-mode].active')[0]?.dataset.mode;if(activeMode)state.mode=activeMode;if(state.mode==='swarm')return swarmRun();return baseRun()};
